27	
28	  // Custom color from user tag metadata. Dynamic hex values must use inline styles
29	  // because Tailwind can't scan dynamically constructed class names.
30	  // Text uses a darkened variant (40% color + black) for contrast on light backgrounds.
31	  const metadata = userTagsSetting ? findTagMetadata(tag, userTagsSetting) : undefined;
32	  const bgHex = colorToHex(metadata?.backgroundColor);
33	  const tagStyle: React.CSSProperties | undefined = bgHex
34	    ? {
35	        borderColor: bgHex,
36	        color: `color-mix(in srgb, ${bgHex} 60%, black)`,
37	        backgroundColor: `color-mix(in srgb, ${bgHex} 15%, transparent)`,
38	        ...style,
39	      }
40	    : style;
41	
42	  const handleTagClick = (e: React.MouseEvent) => {
43	    e.stopPropagation();
44	
45	    // If the tag is clicked in a memo detail page, we should navigate to the memo list page.
46	    if (location.pathname.startsWith("/m")) {
47	      const pathname = parentPage || Routes.HOME;
48	      const searchParams = new URLSearchParams();
49	
50	      searchParams.set("filter", stringifyFilters([{ factor: "tagSearch", value: tag }]));
51	      navigateTo(`${pathname}?${searchParams.toString()}`);
52	      return;
53	    }
54	
55	    const isActive = getFiltersByFactor("tagSearch").some((filter: MemoFilter) => filter.value === tag);
56	    if (isActive) {
57	      removeFilter((f: MemoFilter) => f.factor === "tagSearch" && f.value === tag);
58	    } else {
59	      // Remove all existing tag filters first, then add the new one
60	      removeFilter((f: MemoFilter) => f.factor === "tagSearch");
61	      addFilter({
62	        factor: "tagSearch",
63	        value: tag,
64	      });
65	    }
66	  };
67	
68	  return (
69	    <span
70	      className={cn(tagStyles.base, "cursor-pointer transition-opacity hover:opacity-75", !bgHex && tagStyles.defaultColor, className)}
71	      style={tagStyle}
72	      data-tag={tag}
73	      {...props}
74	      onClick={handleTagClick}
75	    >
